with filtered as (select id, customer_id, device, browser, country, upper(country) as country_upper from sessions where started_at > timestamp '2023-09-13 18:00:00'), filtered_sessions as (select id, customer_id, device, browser, country, country_upper, concat_ws('-', device, browser) as device_browser_key, coalesce(country, 'N/A') as country_filled from filtered where country is not null and customer_id = 19), with_latest as (select s.*, top1.event_type from filtered_sessions s join lateral (select c.event_type from web_events c where c.session_id = s.id order by c.duration_sec desc, c.id desc limit 1) top1 on true), with_last as (select s.*, x.page from with_latest s join lateral (select c.page from web_events c where c.session_id = s.id order by c.event_time desc, c.id desc limit 1) x on true), with_last_sessions as (select s.*, latest.duration_sec, latest.web_event_page from with_last s join lateral (select c.duration_sec, c.page as web_event_page from web_events c where c.session_id = s.id order by c.event_time desc, c.id desc limit 1) latest on true) select s.id, s.customer_id, s.device, s.device_browser_key, s.country_filled, s.event_type, s.duration_sec, s.web_event_page, (select min(x.monthly_fee) from subscriptions x where x.customer_id = s.customer_id) as min_subscription_monthly_fee from with_last_sessions s order by id nulls last limit 20
